public class ClassX {
    private byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                                 + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    /**
     * Hankige konfiguratsioonandmed päringust, kasutades võtmena 'config'.
     * Dekodeerige andmed heksades ja seejärel deserialiseerige need.
