     * @return Deserialiseeritud objekt.
     */
    public Object getConfigData(String config) throws IOException, ClassNotFoundException {
        byte[] decodedBytes = hexStringToByteArray(config);

        try (ByteArrayInputStream bis = new ByteArrayInputStream(decodedBytes);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        }
    }
