import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import javax.xml.bind.DatatypeConverter; // Or helper

public class ClassX {
    private byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                                 + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    /**
     * Obtenha os dados marshalados da solicitação usando 'data' como a chave. Desmarshalize os dados convertendo-os de hexadecimal para bytes. Retorne os dados desmarshalados.
     * 
     * @param data Os dados serializados codificados em hexadecimal.  
     * @return O objeto desmarshalado.
     */
    public Object unmarshalData(String data) throws Exception {
        byte[] bytes = hexStringToByteArray(data);
        try (ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        }
    }
}
