import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import javax.xml.bind.DatatypeConverter; // Or helper

public class ClassX {
    private byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                                 + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    /**
     * Ottieni i dati marshallati dalla richiesta utilizzando 'data' come chiave. 
     * De-marshall i dati convertendoli da esadecimale a byte, 
     * Restituisci i dati de-marshallati.
     * 
     * @param data I dati serializzati codificati in esadecimale. 
     * @return L'oggetto de-marshallato.
     */
    public Object getMarshalledData(String data) throws Exception {
        byte[] bytes = hexStringToByteArray(data);
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
        ObjectInputStream ois = new ObjectInputStream(bis);
        Object obj = ois.readObject();
        ois.close();
        bis.close();
        return obj;
    }
}
