public class ClassX {
    /**
     * Verilen anahtar ve iv için bir parmak izi oluşturun.
     * 
     * @param anahtar: Şifreleme için kullanılan anahtar.
     * @param iv: Şifreleme için kullanılan iv.
     * @return Oluşturulan parmak izi.
     * @throws Exception Eğer şifreleme işlemi sırasında bir hata oluşursa.
     */
    public String createFingerprint(byte[] anahtar, byte[] iv) throws Exception {
        SecretKeySpec secretKeySpec = new SecretKeySpec(anahtar, "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

        // Burada parmak izi için neyin şifreleneceği belirtilmemiş.
        // Genellikle bir parmak izi, bir veri bloğunun veya bir hash'in şifrelenmesiyle oluşturulur.
        // Örnek olarak, basit bir metin şifreleyelim ve sonucunu döndürelim.
        // Gerçek bir parmak izi uygulaması için, bu kısım uygulamanın gereksinimlerine göre değişmelidir.
        String dataToEncrypt = "fingerprint_data"; // Bu kısım uygulamanıza göre değişmeli
        byte[] encryptedBytes = cipher.doFinal(dataToEncrypt.getBytes("UTF-8"));

        // Şifrelenmiş baytları okunabilir bir stringe dönüştürme (örn. Base64)
        return java.util.Base64.getEncoder().encodeToString(encryptedBytes);
    }
}
