     */
    public String createFingerprint(byte[] key, byte[] iv) {
        // Simple approach: concatenate key and IV and then hash (e.g., SHA-256)
        // For demonstration, let's just concatenate and convert to hex string.
        // In a real-world scenario, you'd use a cryptographic hash function.
        StringBuilder sb = new StringBuilder();
        for (byte b : key) {
            sb.append(String.format("%02x", b));
        }
        sb.append("-"); // Separator
        for (byte b : iv) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
