import java.io.*;

public class ClassX {
    /**
     * Create a temporary file with UTF-8 encoding,
     * write the unicode string results to it,
     * and return its path.
     * 
     * :param results: unicode string
     * :return: path of the temporary file
     * :throws IOException: if an I/O error occurs
     */
    public String createTempFile(String results) throws IOException {
        File tempFile = File.createTempFile("tempResults", ".txt");
        String filePath = tempFile.getAbsolutePath();

        try (FileOutputStream fos = new FileOutputStream(tempFile);
             OutputStreamWriter osw = new OutputStreamWriter(fos, "UTF-8");
             BufferedWriter writer = new BufferedWriter(osw)) {

            writer.write(results);
            writer.flush(); // Ensure all data is written to the underlying stream
        }
        // No need to explicitly close streams here, try-with-resources handles it

        return filePath;
    }
}
