import java.io.File;
import java.io.IOException;

public class ClassX {

    /**
     * Delete the image from the given path in the current directory if it exists.
     * 
     * @param path The path of the image to be deleted.
     * @return true if the file was successfully deleted, false otherwise (e.g., file not found, permission denied).
     */
    public boolean deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            System.err.println("Error: Image path cannot be null or empty.");
            return false;
        }

        File file = new File(path);

        if (!file.exists()) {
            System.out.println("Info: File not found at path: " + path);
            return false;
        }

        if (!file.isFile()) {
            System.err.println("Error: Path does not point to a file: " + path);
            return false;
        }

        try {
            if (file.delete()) {
                System.out.println("Success: File deleted: " + path);
                return true;
            } else {
                System.err.println("Error: Failed to delete file: " + path + ". Check permissions or if it's in use.");
                return false;
            }
        } catch (SecurityException e) {
            System.err.println("Security Error: Permission denied to delete file: " + path + ". " + e.getMessage());
            return false;
        }
    }
}
