public class ClassX {

    /**
     * Hapus gambar dari jalur yang diberikan di direktori saat ini jika ada.
     * 
     * @param path Jalur gambar yang akan dihapus.
     */
    public static void deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            System.err.println("Error: Path cannot be null or empty.");
            return;
        }

        File fileToDelete = new File(path);

        if (fileToDelete.exists()) {
            if (fileToDelete.isFile()) { // Ensure it's a file, not a directory
                try {
                    if (fileToDelete.delete()) {
                        System.out.println("Image deleted successfully: " + path);
                    } else {
                        System.err.println("Failed to delete image: " + path + ". Check permissions.");
                    }
                } catch (SecurityException e) {
                    System.err.println("Security Error: No permission to delete image " + path + ". " + e.getMessage());
                }
            } else {
                System.err.println("Error: Path " + path + " is a directory, not a file.");
            }
        } else {
            System.out.println("Image not found at path: " + path);
        }
    }
}
