public class ClassX {
    /**
     * Kunin ang pickled na data mula sa kahilingan gamit ang 'data' bilang susi. Ibalik ang deserialized na pickled na data pagkatapos itong i-convert mula sa hex patungong bytes.
     *
     * @param hexData Ang hex-encoded na string ng pickled data.
     * @return Ang deserialized na object.
     * @throws IOException Kung may error sa I/O habang nagde-deserialize.
     * @throws ClassNotFoundException Kung hindi mahanap ang klase ng serialized na object.
     * @throws DecoderException Kung may error sa pag-decode ng hex string.
     */
    public Object deserializePickledDataFromHex(String hexData) throws IOException, ClassNotFoundException, DecoderException {
        byte[] dataBytes = Hex.decodeHex(hexData);

        try (ByteArrayInputStream bais = new ByteArrayInputStream(dataBytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return ois.readObject();
        }
    }
}
