public class ClassX {
    /**
     * Überprüfen Sie, ob es 'www.example.com/' oder 'beta.example.com/' enthält.
     * 
     * @param query: Die zu überprüfende Abfrage
     * @return: 'Suchergebnisse für: <query>', wenn die Abfrage gültig ist, andernfalls 'Keine Ergebnisse gefunden für: <query>'
     */
    public String checkQuery(String query) {
        // Define the regex pattern to match "www.example.com/" or "beta.example.com/"
        // The parentheses create a group for "www|beta", and backslashes escape the dots.
        Pattern pattern = Pattern.compile("(www|beta)\\.example\\.com/");
        Matcher matcher = pattern.matcher(query);

        // Check if the pattern is found anywhere in the query string
        if (matcher.find()) {
            return "Suchergebnisse für: " + query;
        } else {
            return "Keine Ergebnisse gefunden für: " + query;
        }
    }
}
