import javax.servlet.http.HttpServletRequest;

public class ClassX {
    /**
     * Erhalte die Ziel-URL aus der Anfrage mit 'target_url' und überprüfe, ob sie mit '.com/' endet. Wenn ja, gib 'True' zurück, andernfalls gib 'False' zurück.
     *
     * @param request Das HttpServletRequest-Objekt, das den Parameter 'target_url' enthält.
     * @return True, wenn die 'target_url' existiert und mit '.com/' endet, sonst False.
     */
    public boolean checkTargetUrl(HttpServletRequest request) {
        String targetUrl = request.getParameter("target_url");

        if (targetUrl == null || targetUrl.isEmpty()) {
            return false;
        }

        return targetUrl.endsWith(".com/");
    }
}
