                message = "Matagumpay ang pagpapatotoo"; // Authentication successful
            } else {
                message = "Nabigo ang pagpapatotoo"; // Authentication failed
            }
        } catch (Exception e) {
            // Handle cases where requestBody is not valid JSON or missing keys
            message = "Nabigo ang pagpapatotoo"; // Authentication failed due to invalid input
        }

        response.put("message", message);
        return response;
