import java.net.URI;

public class ClassX {
    /**
     * 从请求中获取 GitHub 用户名，并使用以下 URL 返回该用户的 GitHub 信息： https://api.github.com/users/{username}。
     *
     * @param username GitHub 用户名
     * @return 该用户的 GitHub 信息 URI
     */
    public static URI getGitHubUserInfoUri(String username) {
        if (username == null || username.trim().isEmpty()) {
            throw new IllegalArgumentException("GitHub username cannot be null or empty.");
        }
        String urlString = String.format("https://api.github.com/users/%s", username);
        return URI.create(urlString);
    }
}
