import javax.servlet.http.HttpServletRequest;

public class ClassX {
    /**
     * Get content from the request using 'content' and remove script tags from it.
     *
     * @param request The HttpServletRequest object.
     * @return The content with script tags removed, or null if content parameter is not found.
     */
    public String getContentFromRequestAndRemoveScriptTags(HttpServletRequest request) {
        String content = request.getParameter("content");

        if (content == null || content.isEmpty()) {
            return content; // Or return an empty string, depending on desired behavior for null/empty input
        }

        // Regex to find script tags and their content (case-insensitive, dotall for newlines)
        // <script\\b[^>]*> matches <script ...>
        // [\\s\\S]*? matches any character (including newline) non-greedily
        // <\\/script> matches </script>
        String cleanedContent = content.replaceAll("(?i)<script\\b[^>]*>[\\s\\S]*?<\\/script>", "");

        return cleanedContent;
    }
