import java.util.*;

public class ClassX {

    private Map<String, String> session = new HashMap<>();

    public void login(String username) {
        session.put("username", username);
    }

    public void logout() {
        session.clear();
    }

    /**
     * Render the dashboard.html template if the user has previously authenticated.
     * Otherwise, redirect to the login page.
     * @return: The rendered template or an HTTP redirect.
     */
    public String renderDashboard() {
        if (session.containsKey("username")) {
            return "dashboard.html"; // Simulate rendering the template
        } else {
            return "redirect:/login"; // Simulate an HTTP redirect
        }
    }
}
