    /**
     * Ottieni regex e dati dalla richiesta e cerca la regex nei dati. Se trovata, restituisci "Corrispondenza trovata", altrimenti restituisci "Nessuna corrispondenza trovata".
     * 
     * @param regex La stringa regex da cercare.
     * @param data La stringa di dati in cui cercare la regex.
     * @return risultato della ricerca ("Corrispondenza trovata" o "Nessuna corrispondenza trovata").
     */
    public String searchRegex(String regex, String data) {
        try {
            Pattern pattern = Pattern.compile(regex);
            Matcher matcher = pattern.matcher(data);

            if (matcher.find()) {
                return "Corrispondenza trovata";
            } else {
                return "Nessuna corrispondenza trovata";
            }
        } catch (PatternSyntaxException e) {
            // Gestisci il caso in cui la regex non sia valida
            return "Errore nella sintassi della regex: " + e.getMessage();
        }
    }
}
