    /**
     * Crea un vettore statico, cifra utilizzando AES e modalità CBC. 
     * Quindi, cripta i dati utilizzando la cifra, aggiungendo padding fino alla dimensione del blocco, e restituiscili. 
     * @param data: I dati da criptare. 
     * @param key: La chiave di crittografia. 
     * @return: I dati criptati.
     */
    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        // Create a static IV (Initialization Vector)
        // For production, a randomly generated IV is generally preferred and passed along with the ciphertext.
        // However, the requirement specifies a "static vector".
        byte[] ivBytes = new byte[16]; // 16 bytes for AES block size

        IvParameterSpec ivSpec = new IvParameterSpec(ivBytes);
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding"); // AES, CBC mode, PKCS5Padding
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivSpec);

        return cipher.doFinal(data);
    }
}
