import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * A kérésből szerezd meg a felhasználónevet, és jelenítsd meg ezt a sablonstringben: "<p>Helló {felhasználónév}</p>"
     * 
     * @param username A felhasználónév, amit be kell illeszteni a sablonba.
     * @return renderelt sablonstring
     */
    public String renderUsernameTemplate(String username) {
        // A sablon string
        String template = "<p>Helló {felhasználónév}</p>";

        // Cseréljük ki a helyőrzőt a tényleges felhasználónévre
        String renderedString = template.replace("{felhasználónév}", username);

        return renderedString;
    }
}
