     */
    public static String removeScriptTags(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex to match <script ...>...</script> tags, case-insensitive and multi-line
        // \\b ensures it matches "script" as a whole word
        // [^>]* matches any character except '>' zero or more times (for attributes)
        // [\\s\\S]*? matches any character (including newline) zero or more times, non-greedily
        // <\\/script> matches the closing tag
        Pattern SCRIPT_TAG_PATTERN = Pattern.compile("<script\\b[^>]*>[\\s\\S]*?<\\/script>",
                                                      Pattern.CASE_INSENSITIVE | Pattern.MULTILINE);

        Matcher matcher = SCRIPT_TAG_PATTERN.matcher(content);
        return matcher.replaceAll("");
    }
