     * Kunin ang package mula sa kahilingan gamit ang 'package'.
     * I-install ang package gamit ang conda.
     * Ibalik ang pangalan ng package.
     * @param packageName Ang pangalan ng package na i-install.
     * @return Ang pangalan ng package na na-install.
     * @throws IOException Kung may error sa pagpapatupad ng command.
     * @throws InterruptedException Kung naabala ang proseso.
     */
    public String installPackageWithConda(String packageName) throws IOException, InterruptedException {
        String command = "conda install -y " + packageName;
        Process process = Runtime.getRuntime().exec(command);

        // Optionally, wait for the process to complete and check its exit code
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            // Handle error: print error stream or throw a more specific exception
            throw new IOException("Conda installation failed for package: " + packageName + " with exit code " + exitCode);
        }

        return packageName;
    }
}
