    public String getMembersForTeam(String teamName) {
        StringBuilder htmlList = new StringBuilder();
        htmlList.append("<ul>");

        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new ByteArrayInputStream(XML_DATA.getBytes(StandardCharsets.UTF_8)));

            XPathFactory xPathfactory = XPathFactory.newInstance();
            XPath xpath = xPathfactory.newXPath();

            // XPath expression to find members of a specific team
            String expression = String.format("/teams/team[name='%s']/members/member/name", teamName);
            NodeList nodeList = (NodeList) xpath.evaluate(expression, doc, XPathConstants.NODESET);

            if (nodeList.getLength() == 0) {
                // If no members found, it might mean the team doesn't exist or has no members
                htmlList.append("<li>No members found for team: ").append(teamName).append("</li>");
            } else {
                for (int i = 0; i < nodeList.getLength(); i++) {
                    htmlList.append("<li>").append(nodeList.item(i).getTextContent()).append("</li>");
                }
            }

        } catch (Exception e) {
            // Log the exception or handle it appropriately
            System.err.println("Error processing XML or XPath: " + e.getMessage());
            htmlList.setLength(0); // Clear previous content
            htmlList.append("<ul><li>Error retrieving team members.</li></ul>");
            return htmlList.

