import java.util.logging.Logger;
import javax.servlet.http.HttpServletRequest;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Получите имя пользователя из запроса, используя 'name', и запишите его в журнал, если это не администратор.
     * @param request HttpServletRequest, содержащий параметры запроса.
     */
    public void processUserName(HttpServletRequest request) {
        String userName = request.getParameter("name");

        if (userName != null && !"admin".equalsIgnoreCase(userName)) {
            logger.info("User name received: " + userName);
        } else if (userName == null) {
            logger.warning("User name parameter 'name' was not found in the request.");
        } else {
            // userName is "admin" (case-insensitive)
            logger.info("Admin user detected. Not logging specific name.");
        }
    }
}
