import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;

public class ClassX {
    /**
     * Obtén la URL de la solicitud usando 'url'.
     * Descarga el archivo tomando el parámetro de URL de la solicitud.
     *
     * @param requestUrl La URL del archivo a descargar.
     * @param destinationPath La ruta donde se guardará el archivo descargado.
     * @return La URL de la solicitud si la descarga fue exitosa.
     * @throws IOException Si ocurre un error de I/O durante la descarga.
     */
    public String downloadFileFromUrl(String requestUrl, String destinationPath) throws IOException {
        URL url = new URL(requestUrl);
        Path targetPath = Paths.get(destinationPath);

        try (InputStream in = url.openStream()) {
            Files.copy(in, targetPath, StandardCopyOption.REPLACE_EXISTING);
        }

        return requestUrl;
    }
}
