import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class ClassX {
    /**
     * Obtenha as informações do cabeçalho "Content-Type" da solicitação e defina-o na resposta.  
     * @param request A solicitação HTTP para obter o cabeçalho "Content-Type".
     * @param response A resposta HTTP onde o cabeçalho "Content-Type" será definido.
     * @return A resposta com o cabeçalho "Content-Type".
     */
    public HttpServletResponse setContentTypeFromRequest(HttpServletRequest request, HttpServletResponse response) {
        String contentType = request.getHeader("Content-Type");
        if (contentType != null && !contentType.isEmpty()) {
            response.setHeader("Content-Type", contentType);
        }
        return response;
    }
}
